const data = $json;
const workflowName = (data.workflow && data.workflow.name) || 'desconocido';
const execId = data.execution && data.execution.id;
const nodoFallido = (data.execution && data.execution.lastNodeExecuted) || 'desconocido';
const errorMsg = (data.execution && data.execution.error && data.execution.error.message)
  || JSON.stringify(data).slice(0, 500);

return [{
  json: {
    asunto: `⚠️ Falló workflow: ${workflowName}`,
    html: `<p><b>Workflow:</b> ${workflowName}</p>
           <p><b>Nodo que falló:</b> ${nodoFallido}</p>
           <p><b>Error:</b> ${errorMsg}</p>
           <p><b>Ejecución:</b> ${execId || 'sin id'}</p>`,
  },
}];
